// Package nodelock provides the pinned Node.js release nelm downloads and embeds. The digests are
// committed and embedded rather than fetched, so that they go through code review instead of coming
// from the same host as the artifact they are supposed to vouch for. Generated by scripts/nodelock.
package nodelock

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"slices"
	"strings"
	"sync"
)

const (
	// ChecksumsFileName is only for scripts/nodelock: nothing verifies against a fetched digest.
	ChecksumsFileName = "SHASUMS256.txt"

	distURLTemplate = "https://nodejs.org/dist/v%s/"
	lockFileName    = "data/lock.json"
	sha256HexLen    = 64
)

var (
	//go:embed data/lock.json
	data embed.FS

	readLock = sync.OnceValues(func() (*Lock, error) {
		lockBytes, err := data.ReadFile(lockFileName)
		if err != nil {
			return nil, fmt.Errorf("read %s: %w", lockFileName, err)
		}

		var lock Lock

		if err := json.Unmarshal(lockBytes, &lock); err != nil {
			return nil, fmt.Errorf("decode %s: %w", lockFileName, err)
		}

		if err := lock.Validate(); err != nil {
			return nil, fmt.Errorf("invalid %s, regenerate it with: task node:lock: %w", lockFileName, err)
		}

		return &lock, nil
	})
)

type Platform struct {
	ArchiveSHA256 string `json:"archiveSha256"`
	// BinarySHA256 is the digest of the uncompressed Node.js binary inside the archive, which is what
	// the embedded blob is checked against.
	BinarySHA256 string `json:"binarySha256"`
	// NPMSHA256 is the TreeSHA256 of the npm package inside the archive.
	NPMSHA256 string `json:"npmSha256"`
	// Target is the platform part of the release archive name, such as "linux-x64".
	Target string `json:"target"`
}

func (p *Platform) validate() error {
	if p.Target == "" {
		return errors.New("no target")
	}

	if err := validateSHA256(p.ArchiveSHA256); err != nil {
		return fmt.Errorf("archive sha256: %w", err)
	}

	if err := validateSHA256(p.BinarySHA256); err != nil {
		return fmt.Errorf("binary sha256: %w", err)
	}

	if err := validateSHA256(p.NPMSHA256); err != nil {
		return fmt.Errorf("npm sha256: %w", err)
	}

	return nil
}

type Lock struct {
	// NPMVersion is the version of the npm package the release archives ship.
	NPMVersion string `json:"npmVersion"`
	// Platforms is keyed by "<GOOS>/<GOARCH>".
	Platforms map[string]*Platform `json:"platforms"`
	Version   string               `json:"version"`
}

func (l *Lock) ArchiveURL(goos, goarch string) (string, error) {
	entry, err := l.Get(goos, goarch)
	if err != nil {
		return "", err
	}

	return ArchiveURLFor(l.Version, goos, entry.Target), nil
}

func (l *Lock) Get(goos, goarch string) (*Platform, error) {
	entry, found := l.Platforms[platformKey(goos, goarch)]
	if !found {
		return nil, fmt.Errorf("unsupported platform: %s/%s", goos, goarch)
	}

	return entry, nil
}

func (l *Lock) Validate() error {
	if l.Version == "" {
		return errors.New("no version")
	}

	if strings.HasPrefix(l.Version, "v") {
		return fmt.Errorf("version %q must be recorded without the leading \"v\"", l.Version)
	}

	if l.NPMVersion == "" {
		return errors.New("no npm version")
	}

	if len(l.Platforms) == 0 {
		return errors.New("no platforms")
	}

	for _, platform := range slices.Sorted(maps.Keys(l.Platforms)) {
		goos, goarch, found := strings.Cut(platform, "/")
		if !found || goos == "" || goarch == "" {
			return fmt.Errorf("platform key %q is not \"<os>/<arch>\"", platform)
		}

		entry := l.Platforms[platform]
		if entry == nil {
			return fmt.Errorf("platform %s: no entry", platform)
		}

		if err := entry.validate(); err != nil {
			return fmt.Errorf("platform %s: %w", platform, err)
		}
	}

	return nil
}

func ArchiveURL(goos, goarch string) (string, error) {
	lock, err := Read()
	if err != nil {
		return "", err
	}

	return lock.ArchiveURL(goos, goarch)
}

// ArchiveURLFor is for scripts/nodelock, which builds URLs for a version the lock does not record yet.
func ArchiveURLFor(version, goos, target string) string {
	return DistURLFor(version) + ArchiveNameFor(version, goos, target)
}

func Get(goos, goarch string) (*Platform, error) {
	lock, err := Read()
	if err != nil {
		return nil, err
	}

	return lock.Get(goos, goarch)
}

func Version() (string, error) {
	lock, err := Read()
	if err != nil {
		return "", err
	}

	return lock.Version, nil
}

func ArchiveNameFor(version, goos, target string) string {
	extension := "tar.gz"
	if goos == "windows" {
		extension = "zip"
	}

	return fmt.Sprintf("node-v%s-%s.%s", strings.TrimPrefix(version, "v"), target, extension)
}

func BinaryName(goos string) string {
	if goos == "windows" {
		return "node.exe"
	}

	return "node"
}

func DistURLFor(version string) string {
	return fmt.Sprintf(distURLTemplate, strings.TrimPrefix(version, "v"))
}

func Read() (*Lock, error) {
	return readLock()
}

// TreeSHA256 digests a file tree given the sha256 of every regular file in it, keyed by its
// slash-separated path relative to the tree root. It does not depend on file modes, timestamps or
// how the tree was packed, so the same npm package gives the same digest whether it comes from the
// release archive or from the embedded blob.
func TreeSHA256(fileSHA256s map[string]string) string {
	hasher := sha256.New()

	for _, path := range slices.Sorted(maps.Keys(fileSHA256s)) {
		fmt.Fprintf(hasher, "%s  %s\n", fileSHA256s[path], path)
	}

	return hex.EncodeToString(hasher.Sum(nil))
}

func platformKey(goos, goarch string) string {
	return goos + "/" + goarch
}

func validateSHA256(digest string) error {
	if len(digest) != sha256HexLen {
		return fmt.Errorf("%q is not %d hex characters", digest, sha256HexLen)
	}

	if digest != strings.ToLower(digest) {
		return fmt.Errorf("%q must be lowercase", digest)
	}

	if _, err := hex.DecodeString(digest); err != nil {
		return fmt.Errorf("%q is not hex: %w", digest, err)
	}

	return nil
}
